import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float((0.5 * x1**2 + 0.8 * x2**2 + 0.2 * x1 * x2) * np.exp(0.1 * x1) + 0.05 * x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    if len(x) != 2:
        raise ValueError("Input vector must have dimension 2.")

    x1, x2 = x

    quadratic_output = 0.5 * (x1**2) + 0.8 * (x2**2) + 0.2 * x1 * x2
    skewness_factor = np.exp(x1 * 0.1)
    log_dampening = np.log(1 + np.abs(x1*x2)) * 0.1

    fitness = quadratic_output * skewness_factor + log_dampening

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float((x1**2 + x2**2 + 0.3 * x1 * x2) / (1 + 0.1 * x1**2) * np.exp(0.05 * x1) + 0.2 * x1)

