import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float((0.5 * (x1**2) + 0.8 * (x2**2) + 0.2 * x1 * x2) * np.exp(0.1 * x1) * np.tanh(0.1 * x1) + 0.1*x1 + np.sqrt(np.abs(x1*x2))*0.05)
